package com.tekwatt.admin.controller;import com.tekwatt.admin.dto.*;import com.tekwatt.admin.entity.*;import com.tekwatt.admin.service.GovernanceService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/admin/governance")public class GovernanceController{private final GovernanceService service;public GovernanceController(GovernanceService s){service=s;}@GetMapping("/roles")List<RolePolicy>roles(@RequestParam UUID tenantId){return service.roles(tenantId);}@PutMapping("/roles")RolePolicy role(@RequestParam UUID tenantId,@Valid@RequestBody RolePolicyRequest r){return service.role(tenantId,r);}@GetMapping("/administrators")List<Administrator>admins(@RequestParam UUID tenantId){return service.admins(tenantId);}@PostMapping("/administrators")@ResponseStatus(HttpStatus.CREATED)Administrator admin(@RequestParam UUID tenantId,@Valid@RequestBody AdministratorRequest r){return service.admin(tenantId,null,r);}@PutMapping("/administrators/{id}")Administrator admin(@RequestParam UUID tenantId,@PathVariable UUID id,@Valid@RequestBody AdministratorRequest r){return service.admin(tenantId,id,r);}@DeleteMapping("/administrators/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id){service.deleteAdmin(id);}@GetMapping("/api-keys")List<ApiKeyResponse>keys(@RequestParam UUID tenantId){return service.keys(tenantId);}@PostMapping("/api-keys")@ResponseStatus(HttpStatus.CREATED)ApiKeyResponse key(@RequestParam UUID tenantId,@Valid@RequestBody ApiKeyRequest r){return service.createKey(tenantId,r);}@PostMapping("/api-keys/{id}/disable")ApiKeyResponse disable(@PathVariable UUID id){return service.disableKey(id);}@GetMapping("/settings")Map<String,String>settings(@RequestParam UUID tenantId){return service.getSettings(tenantId);}@PutMapping("/settings")Map<String,String>settings(@RequestParam UUID tenantId,@RequestBody Map<String,String>v){return service.saveSettings(tenantId,v);}}
